<?php
namespace Database\Seeders;
use Illuminate\Database\Seeder;
use Illuminate\Support\Facades\DB;
class StarterRecipesSeeder extends Seeder {
 public function run():void {
  $recipes=[
   ['title'=>'A little Sunday biryani','slug'=>'sunday-biryani','category'=>'Weekend cooking','minutes'=>60,'servings'=>4,'image'=>'assets/recipes/sunday-biryani.webp','description'=>'Fragrant rice, tender chicken and a little time together in the kitchen.','ingredients'=>"500 g chicken pieces\n300 g basmati rice\n2 onions, thinly sliced\n150 g plain yogurt\n1 tbsp ginger-garlic paste\n2 tbsp oil or ghee\n1 tsp ground cumin\n1 tsp ground coriander\n1/2 tsp turmeric\nChilli powder and salt, to taste\nA handful of mint and coriander\nHot water, as needed",'steps'=>"Rinse the rice and soak for 20 minutes. Mix the chicken with yogurt, ginger-garlic paste, ground spices and a little salt. Keep chilled while preparing the onions.\nHeat the oil or ghee in a heavy pot. Cook the onions until golden; reserve some for the top. Add the chicken and its marinade. Cook gently, adding a splash of water if needed, until the chicken is fully cooked.\nBoil the drained rice in plenty of lightly salted water until almost cooked, then drain.\nLayer the rice over the cooked chicken with the mint, coriander and reserved onions. Add a small splash of hot water, cover tightly and cook on low heat for 15 minutes.\nRest, covered, for 10 minutes. Gently lift the layers together and serve hot."] ,
   ['title'=>'Your kind of chicken curry','slug'=>'chicken-curry','category'=>'Everyday favourites','minutes'=>40,'servings'=>4,'image'=>'assets/recipes/chicken-curry.webp','description'=>'A comforting onion-and-tomato chicken curry for an everyday table.','ingredients'=>"500 g chicken pieces\n2 onions, chopped\n2 tomatoes, chopped\n1 tbsp ginger-garlic paste\n2 tbsp oil\n1 tsp ground coriander\n1/2 tsp ground cumin\n1/2 tsp turmeric\nChilli powder and salt, to taste\n250 ml water, plus more if needed\nFresh coriander, to finish",'steps'=>"Heat the oil in a heavy pan. Add the onions and cook until golden.\nStir in the ginger-garlic paste and cook briefly. Add the tomatoes and ground spices, cooking until the tomatoes soften.\nAdd the chicken and stir to coat it in the onion-tomato mixture.\nPour in the water, bring to a simmer and cover. Cook gently until the chicken is fully cooked and the sauce reaches your preferred consistency. Add water if it gets too thick.\nTaste, adjust the seasoning and finish with fresh coriander. Serve hot with rice or roti."] ,
   ['title'=>'Korma for good company','slug'=>'korma','category'=>'Slow weekends','minutes'=>45,'servings'=>4,'image'=>'assets/recipes/chicken-korma.webp','description'=>'A mild, creamy chicken korma with yogurt and cashews. Contains milk and tree nuts.','ingredients'=>"500 g chicken pieces\n2 onions, sliced\n150 g plain yogurt\n40 g cashews, soaked and blended with water\n1 tbsp ginger-garlic paste\n2 tbsp oil or ghee\n1 tsp ground coriander\n1/2 tsp ground cumin\n1/4 tsp turmeric\nSalt and chilli, to taste\nWater, as needed\nCoriander leaves and optional almond slivers, to finish",'steps'=>"Cook the onions in the oil or ghee until soft and golden. Add ginger-garlic paste and ground spices; stir briefly.\nAdd the chicken and cook, turning the pieces to coat them evenly. Lower the heat.\nWhisk the yogurt until smooth. Stir it in gradually on low heat so it does not split, then add the cashew paste and a splash of water.\nCover and simmer gently until the chicken is fully cooked, stirring occasionally and adding water to keep the sauce smooth.\nTaste and adjust the seasoning. Finish with coriander and optional almond slivers, then serve hot with rice or naan."]
  ];
  foreach($recipes as $data){$current=DB::table('recipes')->where('slug',$data['slug'])->first();if(!$current)DB::table('recipes')->insert($data+['active'=>true,'created_at'=>now(),'updated_at'=>now()]);elseif(str_starts_with($current->description,'A sample recipe card for the Minitz kitchen.'))DB::table('recipes')->where('id',$current->id)->update($data+['updated_at'=>now()]);elseif(in_array($current->image,['assets/artwork-06.jpg','assets/artwork-07.jpg','assets/artwork-08.jpg']))DB::table('recipes')->where('id',$current->id)->update(['image'=>$data['image'],'updated_at'=>now()]);}
 }
}
